@Component
public class ReportRenderer {
 static class BoundedOutput extends FilterOutputStream {long count;BoundedOutput(OutputStream out){super(out);}public void write(byte[] b,int off,int len)throws IOException{count+=len;if(count>MAX_BYTES)throw new ReportFailure("limit-exceeded");out.write(b,off,len);}public void write(int b)throws IOException{if(++count>MAX_BYTES)throw new ReportFailure("limit-exceeded");out.write(b);}}
 static final long MAX_BYTES=50L*1024*1024;
 static final Map<String,Color> COLORS=Map.of("processing",new Color(31,164,131),"idle",new Color(93,147,221),"maintenance",new Color(134,108,203),"dummy",new Color(37,175,194),"fault",new Color(220,91,102),"paused",new Color(226,166,67),"unknown",new Color(161,170,186),"mixed",new Color(112,127,154));
 final ObjectMapper json; final java.awt.Font chartFont;
 public ReportRenderer(ObjectMapper json){this.json=json;try(var font=getClass().getResourceAsStream("/fonts/NotoSansCJKtc-Regular.otf")){chartFont=java.awt.Font.createFont(java.awt.Font.TRUETYPE_FONT,font);}catch(Exception e){throw new IllegalStateException("report font unavailable",e);}}
 static Object value(JsonNode n){if(n==null||n.isMissingNode()||n.isNull())return null;if(n.isNumber())return n.numberValue();if(n.isBoolean())return n.booleanValue();return n.isTextual()?n.asText():n.toString();}
 static void row(Sheet s,Object... values){var r=s.createRow(s.getLastRowNum()==0&&s.getRow(0)==null?0:s.getLastRowNum()+1);CellStyle initialHeader=null;if(r.getRowNum()==0){initialHeader=s.getWorkbook().createCellStyle();initialHeader.setFillForegroundColor(IndexedColors.CORNFLOWER_BLUE.getIndex());initialHeader.setFillPattern(FillPatternType.SOLID_FOREGROUND);var f=s.getWorkbook().createFont();f.setBold(true);f.setColor(IndexedColors.WHITE.getIndex());initialHeader.setFont(f);}for(int i=0;i<values.length;i++){var c=r.createCell(i);if(initialHeader!=null)c.setCellStyle(initialHeader);Object v=values[i];if(v instanceof Number n)c.setCellValue(n.doubleValue());else if(v instanceof Boolean b)c.setCellValue(b);else {String text=v==null?"—":v.toString();if(text.length()>32700)throw new ReportFailure("limit-exceeded");c.setCellValue(text);}}}
 static void dataRow(Sheet s,JsonNode n,String... fields){row(s,Arrays.stream(fields).map(f->value(n.path(f))).toArray());}
 static void section(Sheet s,String title){row(s,title);}
 List<Map<String,Object>> chartSeries(String dataset,ObjectNode s){var out=new ArrayList<Map<String,Object>>();
  if(dataset.equals("states")){for(String state:StatisticsStore.STATES){double total=0;for(var eq:s.path("equipment"))total+=eq.path("states").path(state).asDouble();out.add(Map.of("label",state,"value",total));}}
  if(dataset.equals("production"))for(var eq:s.path("equipment"))out.add(Map.of("label",eq.path("equipmentId").asText(),"value",eq.path("production").path("completed").asDouble(),"secondary",eq.path("production").path("scrapped").asDouble()));
  if(dataset.equals("kla")){var buckets=new TreeMap<Long,double[]>();long start=Instant.parse(s.path("start").asText()).getEpochSecond(),end=Instant.parse(s.path("end").asText()).getEpochSecond(),width=Math.max(1,(end-start+359)/360);for(var m:s.path("kla"))if(m.path("meanNm").isNumber()){long epoch=Instant.parse(m.path("completedAt").asText()).getEpochSecond();var v=buckets.computeIfAbsent(Math.floorDiv(epoch,width)*width,k->new double[2]);v[0]+=m.path("meanNm").asDouble();v[1]++;}buckets.forEach((epoch,v)->out.add(Map.of("label",Instant.ofEpochSecond(epoch).atZone(ZoneId.of("Asia/Taipei")).toLocalTime().toString(),"value",v[0]/v[1])));}
  if(dataset.equals("vision")){var counts=new TreeMap<String,Long>();for(var v:s.path("vision"))for(var c:v.path("candidates"))counts.merge(c.asText(),1L,Long::sum);counts.forEach((k,v)->out.add(Map.of("label",k,"value",v)));}
  if(dataset.equals("phm")){var buckets=new TreeMap<Long,double[]>();for(var eq:s.path("phm"))for(var p:eq.path("pumps"))for(var point:p.path("trend"))if(point.path("health").isNumber()){var v=buckets.computeIfAbsent(point.path("epoch").asLong(),k->new double[2]);double samples=point.path("samples").asDouble(1);v[0]+=point.path("health").asDouble()*samples;v[1]+=samples;}buckets.forEach((epoch,v)->out.add(Map.of("label",Instant.ofEpochSecond(epoch).atZone(ZoneId.of("Asia/Taipei")).toLocalTime().toString(),"value",v[0]/v[1])));}
  return out;
 }
 byte[] chart(String dataset,ObjectNode s)throws IOException{
  int width=1200,height=520;var image=new BufferedImage(width,height,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(Color.WHITE);g.fillRect(0,0,width,height);g.setFont(chartFont.deriveFont(17f));String lang=s.path("language").asText();g.setColor(new Color(38,55,80));String title=ReportText.label(lang,dataset);if(dataset.equals("kla"))title+=" · meanNm / nm";if(dataset.equals("vision"))title+=" · candidate occurrences (not wafer yield)";if(dataset.equals("phm"))title+=" · event-weighted health / 100";g.drawString(title,35,35);
  if(dataset.equals("timeline")){long begin=Instant.parse(s.path("start").asText()).getEpochSecond(),end=Instant.parse(s.path("end").asText()).getEpochSecond();int i=0;for(var eq:s.path("equipment")){int y=75+i++*35;g.setColor(new Color(38,55,80));g.drawString(eq.path("equipmentId").asText(),20,y+18);for(var b:eq.path("timeline")){long a=Instant.parse(b.path("start").asText()).getEpochSecond(),z=Instant.parse(b.path("end").asText()).getEpochSecond();int x=250+(int)(900.0*(a-begin)/Math.max(1,end-begin)),w=Math.max(1,(int)(900.0*(z-a)/Math.max(1,end-begin)));g.setColor(COLORS.getOrDefault(b.path("state").asText(),COLORS.get("mixed")));g.fillRect(x,y,w,23);}}g.setColor(Color.DARK_GRAY);g.drawString(s.path("start").asText()+" — "+s.path("end").asText(),250,450);g.drawString("resolution: "+s.path("resolutionSeconds").asText()+" s; mixed buckets retain per-state durations in table",35,490);
  }else{var series=chartSeries(dataset,s);if(series.isEmpty()){g.setColor(Color.GRAY);g.drawString(ReportText.label(lang,"unknown"),80,200);}else if(dataset.equals("states")){double total=series.stream().mapToDouble(x->((Number)x.get("value")).doubleValue()).sum();double angle=90;int i=0;for(var point:series){double n=((Number)point.get("value")).doubleValue(),arc=total==0?0:360*n/total;g.setColor(COLORS.get(point.get("label")));g.fillArc(90,90,300,300,(int)angle,-(int)Math.ceil(arc));angle-=arc;g.fillRect(470,85+48*i,18,18);g.setColor(Color.DARK_GRAY);g.drawString(ReportText.label(lang,(String)point.get("label"))+"  "+String.format(Locale.ROOT,"%.0f s (%.1f%%)",n,total==0?0:n*100/total),510,102+48*i++);}g.setColor(Color.WHITE);g.fillOval(163,163,154,154);
   }else{double max=series.stream().mapToDouble(x->Math.max(((Number)x.get("value")).doubleValue(),((Number)x.getOrDefault("secondary",0)).doubleValue())).max().orElse(1);max=Math.max(1,max);int count=series.size();double step=1050.0/Math.max(1,count-1);g.setColor(new Color(219,226,237));g.drawLine(85,400,1140,400);g.setColor(Color.GRAY);g.drawString(String.format(Locale.ROOT,"%.2f",max),20,90);g.drawString("0",35,400);int lastX=0,lastY=0;for(int i=0;i<count;i++){var point=series.get(i);double v=((Number)point.get("value")).doubleValue();int x=85+(int)(i*step),y=400-(int)(v*300/max);g.setColor(new Color(48,115,218));if(dataset.equals("kla")||dataset.equals("phm")){g.fillOval(x-4,y-4,8,8);if(i>0)g.drawLine(lastX,lastY,x,y);lastX=x;lastY=y;}else{g.fillRect(x,y,(int)Math.max(1,step/3),400-y);if(point.containsKey("secondary")){int sy=400-(int)(((Number)point.get("secondary")).doubleValue()*300/max);g.setColor(new Color(220,91,102));g.fillRect(x+(int)(step/3),sy,(int)Math.max(1,step/3),400-sy);}}g.setColor(Color.DARK_GRAY);if(count<=30)g.drawString(String.format(Locale.ROOT,"%.1f",v),x,y-9);String label=point.get("label").toString();if(label.startsWith("TEL-"))label=label.substring(label.length()-2);if(count<=30||i%Math.max(1,count/8)==0)g.drawString(label.substring(0,Math.min(label.length(),14)),x,430+(i%2)*22);}if(dataset.equals("production")){g.setColor(new Color(48,115,218));g.drawString(ReportText.label(lang,"completed"),800,55);g.setColor(new Color(220,91,102));g.drawString(ReportText.label(lang,"scrapped"),990,55);}
   }}g.dispose();var bytes=new ByteArrayOutputStream();ImageIO.write(image,"png",bytes);return bytes.toByteArray();
 }
 ObjectNode render(Path dir,ObjectNode snapshot,ObjectNode analysis,String id)throws IOException{
  Files.createDirectories(dir);String lang=snapshot.path("language").asText();var manifest=json.createObjectNode();manifest.set("analysis",analysis);manifest.set("snapshot",snapshot);manifest.put("snapshotHash",ReportData.hash(snapshot));var chartList=manifest.putArray("charts");
  try(var book=new SXSSFWorkbook(100)){
   book.setCompressTempFiles(true);
   var summary=book.createSheet(ReportText.label(lang,"summary"));row(summary,ReportText.label(lang,"summary"));row(summary,ReportText.label(lang,"notice"));row(summary,ReportText.label(lang,"basis"));row(summary,ReportText.label(lang,"denominator"));row(summary,snapshot.path("start").asText(),snapshot.path("end").asText(),"Asia/Taipei");
   for(var text:analysis.path("sections")){row(summary,text.path("title").asText());row(summary,text.path("text").asText());row(summary,"refs",text.path("refs").toString());}
   var eq=book.createSheet(ReportText.label(lang,"equipment"));row(eq,"equipmentId",ReportText.label(lang,"utilization"),ReportText.label(lang,"pmUtilization"),ReportText.label(lang,"coverage"),ReportText.label(lang,"completed"),ReportText.label(lang,"scrapped"),ReportText.label(lang,"dummyCompleted"),ReportText.label(lang,"dummyScrapped"),"productionCoverage (%)","quality");for(var e:snapshot.path("equipment"))row(eq,e.path("equipmentId").asText(),value(e.path("utilization").path("utilization")),value(e.path("utilization").path("pmUtilization")),value(e.path("coverage")),value(e.path("production").path("completed")),value(e.path("production").path("scrapped")),value(e.path("production").path("dummyCompleted")),value(e.path("production").path("dummyScrapped")),value(e.path("production").path("coverage")),e.path("production").path("quality").asText());
   var timeline=book.createSheet(ReportText.label(lang,"timeline"));row(timeline,"equipmentId","start (UTC)","end (UTC)","state","flags","processing (s)","idle (s)","maintenance (s)","dummy (s)","fault (s)","paused (s)","unknown (s)");for(var e:snapshot.path("equipment"))for(var b:e.path("timeline")){var v=new ArrayList<Object>(List.of(e.path("equipmentId").asText(),b.path("start").asText(),b.path("end").asText(),ReportText.label(lang,b.path("state").asText()),b.path("flags").toString()));for(String state:StatisticsStore.STATES)v.add(value(b.path("states").path(state)));row(timeline,v.toArray());}
   var kla=book.createSheet(ReportText.label(lang,"kla"));String[] k={"equipmentId","waferId","id","revision","completedAt","purpose","pm","meanNm","minNm","maxNm","uniformityPct","thicknessQuality","defectQuality","modelVersion","synthetic"};row(kla,(Object[])k);for(var m:snapshot.path("kla"))dataRow(kla,m,k);
   var vision=book.createSheet(ReportText.label(lang,"vision"));String[] v={"equipmentId","waferId","runId","measurementId","revision","completedAt","kind","purpose","mode","datasetId","datasetVersion","quality","algorithmVersion","candidates","defectCount"};row(vision,(Object[])v);for(var m:snapshot.path("vision"))dataRow(vision,m,v);
   var phm=book.createSheet(ReportText.label(lang,"phm"));row(phm,"equipmentId","pumpId","lastHistorical (UTC)","health / 100","remaining simulated cycles","passRate (%)","passed","failed","interrupted");for(var e:snapshot.path("phm"))for(var p:e.path("pumps"))row(phm,e.path("equipmentId").asText(),p.path("pumpId").asText(),value(p.path("lastHistorical").path("time")),value(p.path("lastHistorical").path("health")),value(p.path("lastHistorical").path("remainingCycles")),value(p.path("passRate")),value(p.path("counts").path("passed")),value(p.path("counts").path("failed")),value(p.path("counts").path("interrupted")));
   section(phm,"Event-based historical observations; bucket seconds: "+snapshot.path("phmResolutionSeconds").asText());row(phm,"equipmentId","pumpId","epoch (UTC)","health","pressureMin (mbar)","pressureMax (mbar)","samples");for(var e:snapshot.path("phm"))for(var p:e.path("pumps"))for(var t:p.path("trend"))row(phm,e.path("equipmentId").asText(),p.path("pumpId").asText(),value(t.path("epoch")),value(t.path("health")),value(t.path("pressureMin")),value(t.path("pressureMax")),value(t.path("samples")));
   var quality=book.createSheet(ReportText.label(lang,"quality"));row(quality,ReportText.label(lang,"notice"));row(quality,ReportText.label(lang,"basis"));row(quality,ReportText.label(lang,"denominator"));row(quality,"equipmentId","coverage (%)","unknown (s)","productionQuality","productionCoverage (%)","pending KLA","pending vision");for(var e:snapshot.path("equipment")){JsonNode pending=snapshot.path("pending").findValues("equipmentId").isEmpty()?json.nullNode():snapshot.path("pending");JsonNode p=json.nullNode();for(var a:pending)if(a.path("equipmentId").equals(e.path("equipmentId")))p=a;row(quality,e.path("equipmentId").asText(),value(e.path("coverage")),value(e.path("states").path("unknown")),e.path("production").path("quality").asText(),value(e.path("production").path("coverage")),value(p.path("kla")),value(p.path("vision")));}
   var info=book.createSheet(ReportText.label(lang,"info"));row(info,"reportId",id);row(info,"snapshotHash",ReportData.hash(snapshot));row(info,"model",analysis.path("model").asText());row(info,"promptVersion",analysis.path("promptVersion").asText());row(info,"usage",analysis.path("usage").toString());row(info,"language",lang);row(info,"phmTrendSource",snapshot.path("phmTrendSource").asText("vacuum-event-observations"));row(info,"timezone","Asia/Taipei");row(info,"start",snapshot.path("start").asText());row(info,"end",snapshot.path("end").asText());row(info,"resolutionSeconds",snapshot.path("resolutionSeconds").asInt());for(var src:snapshot.path("sources"))row(info,src.path("source").asText(),src.path("capturedAt").asText());
   int anchorRow=summary.getLastRowNum()+3;for(var c:analysis.path("charts")){String ds=c.path("dataset").asText();byte[] bytes=chart(ds,snapshot);Files.write(dir.resolve(ds+".png"),bytes);chartList.addObject().put("dataset",ds).put("type",c.path("type").asText()).put("title",ReportText.label(lang,ds));int index=book.addPicture(bytes,Workbook.PICTURE_TYPE_PNG);var draw=summary.createDrawingPatriarch();var anchor=new XSSFClientAnchor();anchor.setCol1(0);anchor.setCol2(12);anchor.setRow1(anchorRow);anchor.setRow2(anchorRow+24);draw.createPicture(anchor,index);anchorRow+=27;}
   var header=book.createCellStyle();header.setFillForegroundColor(IndexedColors.CORNFLOWER_BLUE.getIndex());header.setFillPattern(FillPatternType.SOLID_FOREGROUND);var font=book.createFont();font.setBold(true);font.setColor(IndexedColors.WHITE.getIndex());header.setFont(font);for(var sheet:book){sheet.createFreezePane(0,1);if(sheet.getRow(0)!=null)for(var cell:sheet.getRow(0))cell.setCellStyle(header);for(int col=0;col<16;col++)sheet.setColumnWidth(col,24*256);sheet.setAutobreaks(true);sheet.getPrintSetup().setLandscape(true);sheet.getPrintSetup().setFitWidth((short)1);if(sheet.getLastRowNum()>0&&sheet!=summary)sheet.setAutoFilter(new CellRangeAddress(0,sheet.getLastRowNum(),0,sheet.getRow(0)==null?15:Math.max(0,sheet.getRow(0).getLastCellNum()-1)));}
   // Wrapped summary paragraphs remain readable in Excel rather than clipped.
   var wrapped=book.createCellStyle();wrapped.setWrapText(true);for(int r=1;r<anchorRow;r++){var line=summary.getRow(r);if(line!=null&&line.getLastCellNum()==1){summary.addMergedRegion(new CellRangeAddress(r,r,0,11));line.getCell(0).setCellStyle(wrapped);line.setHeightInPoints(line.getCell(0).getStringCellValue().length()>130?65:40);}}
   Path temp=dir.resolve("report.tmp");try(var output=Files.newOutputStream(temp)){book.write(new BoundedOutput(output));}Files.move(temp,dir.resolve("report.xlsx"),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);
  }
  Files.writeString(dir.resolve("manifest.json"),manifest.toString());return manifest;
 }
}
